const D = { energy:.6, scale:1, density:.5, speed:1, morph:.405, hue:32, x:.5, y:.5, style:'pavement', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const hs = n => { const s = Math.sin(n*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const fr = (i,j) => hs(i*57.3 + j*131.9 + 3.7);
const vn = (x,y) => { const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=fr(ix,iy), b=fr(ix+1,iy), c=fr(ix,iy+1), d=fr(ix+1,iy+1);
  return a + (b-a)*wx + (c-a)*wy + (a-b-c+d)*wx*wy; };
const fbm = (x,y) => .58*vn(x,y) + .27*vn(x*2.1+5.3, y*2.1-3.7) + .15*vn(x*4.3-1.9, y*4.3+6.1);

const sty = P.style;
const ink = (sty==='ink'), riso = (sty==='riso'), fld = (sty==='field'), ena = (sty==='enamel');
const H = ((P.hue%360)+360)%360;

// ---- real-time drift + the family morph -------------------------------------
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
const rate = P.speed * (.45 + .5*K.intensity);
S.dx = (S.dx||0) + dt*rate*.135;
S.dy = (S.dy||0) + dt*rate*.083;      // incommensurate with dx -> never re-tiles the same way
const bass = (S.b = (S.b||0)*.82 + (A.bass||0)*.18);
const glow = (.40 + .60*P.energy)*(.55 + .5*K.intensity) + bass*.3;

// The pentagon family. h -> 0 : squares on the diagonal.  h = 0.4226 : Cairo
// (angles 120/90/120/90/120, the dual snub square).  h = 0.5486 : equilateral
// Cairo.  h -> 1 : basketweave rectangles.  Morphing h moves EVERY vertex.
const h0 = .05 + cl(P.morph,0,1)*.92;
const wob = .55*Math.sin(K.t*.071) + .30*Math.sin(K.t*.163+1.1) + .15*Math.sin(K.t*.397+2.3);
const hm = cl(h0 + .36*P.energy*wob, .06, .96);

const rot = K.t*.0135 + .09*Math.sin(K.t*.059+.4) + .04*Math.sin(K.t*.147+2.1);
const ca = Math.cos(rot), sa = Math.sin(rot);
let SC = u*.085*cl(P.scale,.3,2.2);
SC = Math.max(SC, Math.sqrt(width*height/150)*.5);      // hard cap: ~150 cells on screen
const ox = cl(P.x,.1,.9)*width, oy = cl(P.y,.1,.9)*height;
const pX = S.dx, pY = S.dy;
const TS = (lx,ly) => { const rx = lx - pX, ry = ly - pY;
  return [ox + (rx*ca - ry*sa)*SC, oy + (rx*sa + ry*ca)*SC]; };
const IV = (sx,sy) => { const dx=(sx-ox)/SC, dy=(sy-oy)/SC;
  return [dx*ca + dy*sa + pX, -dx*sa + dy*ca + pY]; };

// ---- palette ----------------------------------------------------------------
let GC;
if (ink)       GC = [40, 8, 88];
else if (riso) GC = [38, 6, 93];
else if (fld)  GC = [H, 40, 8];
else if (ena)  GC = [H, 30, 7];
else           GC = [H, 12, 13];
noStroke(); fill(GC[0], GC[1], GC[2], 100); rect(0,0,width,height);

// ---- visible lattice window -------------------------------------------------
const cs = [IV(0,0), IV(width,0), IV(0,height), IV(width,height)];
let mnx=1e9, mxx=-1e9, mny=1e9, mxy=-1e9;
for (let i=0;i<4;i++){ mnx=Math.min(mnx,cs[i][0]); mxx=Math.max(mxx,cs[i][0]);
                       mny=Math.min(mny,cs[i][1]); mxy=Math.max(mxy,cs[i][1]); }
const i0 = Math.floor((mnx-2.2)/2), i1 = Math.ceil((mxx+2.2)/2);
const j0 = Math.floor((mny-2.2)/2), j1 = Math.ceil((mxy+2.2)/2);

function pent(cx,cy,kind,h){
  if (kind===0) return [[cx,cy+h],[cx+1,cy+1],[cx+2-h,cy],[cx+1,cy-1],[cx,cy-h]];   // E of an even cell
  if (kind===1) return [[cx,cy+h],[cx-1,cy+1],[cx-2+h,cy],[cx-1,cy-1],[cx,cy-h]];   // W of an even cell
  if (kind===2) return [[cx-h,cy],[cx-1,cy+1],[cx,cy+2-h],[cx+1,cy+1],[cx+h,cy]];   // N of an odd cell
  return [[cx-h,cy],[cx-1,cy-1],[cx,cy-2+h],[cx+1,cy-1],[cx+h,cy]];                 // S of an odd cell
}

const jw = Math.max(.8, SC*.055);                 // joint / cell-wall weight
const orn = cl(P.density,0,1);
const drift = K.t*.037;

for (let j=j0; j<=j1; j++){
  for (let i=i0; i<=i1; i++){
    const cx = 2*i, cy = 2*j, even = ((i+j)&1)===0;
    for (let k=0;k<2;k++){
      const kind = even ? k : 2+k;
      const q = pent(cx, cy, kind, hm);
      let gx=0, gy=0;
      for (let v=0;v<5;v++){ gx+=q[v][0]; gy+=q[v][1]; }
      gx/=5; gy/=5;
      const tv = fr(i*3+kind, j*5+1);
      const fv = fbm(gx*.14 + drift*.5, gy*.14 - drift*.31);
      let cc;
      if (ink)       cc = [40, 6, cl(94 - 10*tv - 14*(kind>1?1:0), 40, 98)];
      else if (riso) cc = (kind%2===0) ? [338, cl(28 + 44*fv, 8, 82), cl(96 - 22*fv, 44, 98)]
                                       : [212, cl(30 + 46*fv, 8, 82), cl(94 - 26*fv, 40, 98)];
      else if (fld)  cc = [(H + fv*150 + kind*6) % 360, cl(38 + 44*fv, 8, 92), cl(10 + 74*fv*fv*1.5 + 8*tv, 5, 92)];
      else if (ena)  cc = [(H + kind*46 + tv*18) % 360, cl(56 + 22*fv, 20, 90), cl(30 + 46*fv + 12*tv, 12, 88)];
      else {                                       // pavement: cast concrete, four castings
        const shade = [.62,.44,.86,.52][kind];
        cc = [(H + tv*14 - 6) % 360, cl(9 + 8*tv + 5*fv, 2, 26), cl(24 + 46*shade + 16*fv + 8*tv, 8, 86)];
      }
      const pj = [];
      for (let v=0;v<5;v++) pj.push(TS(q[v][0], q[v][1]));
      // fill + stroke in ONE shape call
      if (ink) noFill(); else fill(cc[0], cc[1], cc[2], 100);
      if (fld) noStroke();
      else { stroke(ink?28:(riso?338:H), ink?30:(riso?60:(ena?40:14)),
                    ink?12:(riso?42:(ena?6:9)), ink?92:(riso?70:88));
             strokeWeight(ink ? Math.max(1, SC*.038*(1+.5*tv)) : jw); }
      beginShape(); for (let v=0;v<5;v++) vertex(pj[v][0], pj[v][1]); endShape(CLOSE);
      // ornament: an inset course inside every tile, then a centre stud
      if (orn > .15 && SC > 26){
        const f2 = 1 - .14 - .16*orn;
        const c2 = TS(gx, gy);
        noFill();
        stroke(ink?28:H, ink?26:(fld?20:12), ink?18:(fld?96:(ena?92:74)),
               cl((ink?46:24) + 40*orn*(fld?glow:1), 0, 84));
        strokeWeight(Math.max(.8, jw*.6));
        beginShape();
        for (let v=0;v<5;v++) vertex(c2[0] + (pj[v][0]-c2[0])*f2, c2[1] + (pj[v][1]-c2[1])*f2);
        endShape(CLOSE);
        if (orn > .62 && SC > 44){
          noStroke(); fill(ink?28:H, ink?26:cl(cc[1]*.5,0,100), ink?16:cl(cc[2]*1.5+14,4,98), 80);
          ellipse(c2[0], c2[1], SC*.16*orn, SC*.16*orn);
        }
      }
    }
  }
}

// ---- a light sweeping the plane, out of phase with the morph ---------------
if (!ink && !riso){
  push(); blendMode(ADD); noStroke();
  const lxx = ox + Math.cos(K.t*.083 + 1.2)*width*.42 + Math.cos(K.t*.211)*width*.10;
  const lyy = oy + Math.sin(K.t*.127 + .3)*height*.40 + Math.sin(K.t*.317+2)*height*.09;
  for (let i=5;i>=1;i--){ fill(H, fld?24:20, 100, 1.4 + 2.6*glow); ellipse(lxx, lyy, u*.20*i, u*.20*i); }
  pop(); blendMode(BLEND);
}
if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
